/**
 * Creates a flag: a PlaneGeometry mesh attached to a pole cylinder at x = 0.
 * The undeformed vertex positions are cached in mesh.userData.basePositions
 * so waveFlag never compounds deformation.
 */
export function createFlag({ width = 3, height = 2, segsX = 30, segsY = 20 } = {}) {
  const geometry = new THREE.PlaneGeometry(width, height, segsX, segsY);
  // PlaneGeometry is centered; shift so the hoist edge sits at x = 0.
  geometry.translate(width / 2, 0, 0);

  const material = new THREE.MeshBasicMaterial({ color: 0xff0000, side: THREE.DoubleSide });
  const flag = new THREE.Mesh(geometry, material);

  // Pole cylinder along the hoist edge (x = 0).
  const poleHeight = height * 1.5;
  const poleGeometry = new THREE.CylinderGeometry(0.05, 0.05, poleHeight, 12);
  const pole = new THREE.Mesh(
    poleGeometry,
    new THREE.MeshBasicMaterial({ color: 0x888888 })
  );
  pole.position.set(0, 0, 0);
  flag.add(pole);
  flag.userData.pole = pole;

  // Cache the undeformed positions.
  flag.userData.basePositions = Float32Array.from(geometry.attributes.position.array);

  return flag;
}

/** Amplitude grows linearly from the hoist edge. */
function amp(x, width) {
  return 0.25 * (x / width);
}

/**
 * Displace each vertex z by amp(x) * sin(3*x - 2.5*t).
 * Uses cached base positions, so repeated calls do not compound.
 */
export function waveFlag(mesh, t) {
  const base = mesh.userData.basePositions;
  if (!base) {
    throw new Error('waveFlag requires cached basePositions in userData');
  }
  const posAttr = mesh.geometry.attributes.position;
  const arr = posAttr.array;
  const width = mesh.geometry.parameters.width;

  for (let i = 0; i < arr.length; i += 3) {
    const x = base[i];
    const z = amp(x, width) * Math.sin(3 * x - 2.5 * t);
    arr[i] = base[i];
    arr[i + 1] = base[i + 1];
    arr[i + 2] = z;
  }

  posAttr.needsUpdate = true;
}
