result = await mcp.call_tool("tools", "ox-bridge-write", {"path": "/workspace/test/flag.test.js", "content": "import { describe, it, expect } from 'vitest';
import * as THREE from 'three';
import { createFlag, waveFlag } from '../src/flag.js';

describe('flag', () => {
  const width = 3;
  const height = 2;
  const segsX = 30;
  const segsY = 20;

  function makeFlag() {
    return createFlag({ width, height, segsX, segsY });
  }

  function positions(mesh) {
    return mesh.geometry.attributes.position.array;
  }

  it('hoist-edge vertices (x = 0) have z = 0 exactly after waveFlag', () => {
    const flag = makeFlag();
    waveFlag(flag, 1.3);
    const pos = positions(flag);
    let hoistCount = 0;
    for (let i = 0; i < pos.length; i += 3) {
      if (pos[i] === 0) {
        hoistCount++;
        expect(pos[i + 2]).toBe(0);
      }
    }
    // sanity: there should be a full column of hoist vertices
    expect(hoistCount).toBe(segsY + 1);
  });

  it('free-edge vertices (max x) have |z| up to 0.25 and at least one exceeds 0.1', () => {
    const flag = makeFlag();
    waveFlag(flag, 1.3);
    const pos = positions(flag);
    let count = 0;
    let maxAbsZ = 0;
    let exceeding = 0;
    for (let i = 0; i < pos.length; i += 3) {
      if (pos[i] === width) {
        count++;
        const az = Math.abs(pos[i + 2]);
        maxAbsZ = Math.max(maxAbsZ, az);
        if (az > 0.1) exceeding++;
      }
    }
    expect(count).toBeGreaterThan(0);
    expect(maxAbsZ).toBeLessThanOrEqual(0.25);
    expect(exceeding).toBeGreaterThan(0);
  });

  it('calling waveFlag twice with the same t leaves the buffer identical', () => {
    const flag = makeFlag();
    waveFlag(flag, 1.3);
    const once = Float32Array.from(positions(flag));
    waveFlag(flag, 1.3);
    const twice = positions(flag);
    expect(twice.length).toBe(once.length);
    for (let i = 0; i < once.length; i++) {
      expect(twice[i]).toBe(once[i]);
    }
  });

  it('t = 0 versus t = 1 differ', () => {
    const a = makeFlag();
    waveFlag(a, 0);
    const b = makeFlag();
    waveFlag(b, 1);
    const pa = positions(a);
    const pb = positions(b);
    expect(pa.length).toBe(pb.length);
    let differs = false;
    for (let i = 0; i < pa.length; i++) {
      if (pa[i] !== pb[i]) {
        differs = true;
        break;
      }
    }
    expect(differs).toBe(true);
  });

  it('is a Mesh with PlaneGeometry attached to a pole cylinder at x = 0', () => {
    const flag = makeFlag();
    expect(flag).toBeInstanceOf(THREE.Mesh);
    expect(flag.geometry).toBeInstanceOf(THREE.PlaneGeometry);
    expect(flag.geometry.parameters.width).toBe(width);
    expect(flag.userData.pole).toBeInstanceOf(THREE.Mesh);
    expect(flag.userData.pole.geometry).toBeInstanceOf(THREE.CylinderGeometry);
    expect(flag.userData.pole.position.x).toBe(0);
  });
});
